std::string AgentHost::post_printer_event(const PrinterEvent& event)
{
    if (event.printer.empty())
        throw std::invalid_argument("A print marker names its printer.");
    ConversationMessage note;
    // The page draws the marker from its data; the text is the same line for
    // a page that does not know the marker.
    if (event.kind == PrinterEvent::kSent)
        note.text = "Sent to " + event.printer;
    else if (event.kind == PrinterEvent::kUploaded)
        note.text = "Uploaded to " + event.printer + " · not started";
    else
        throw std::invalid_argument("Unknown print marker kind \"" + event.kind + "\".");
    json data{{"kind", event.kind}, {"printer", event.printer}};
    if (event.plate > 0)
        data["plate"] = event.plate;
    if (!event.plate_name.empty())
        data["plateName"] = event.plate_name;
    note.printer_event = data.dump();
    return append_note(std::move(note));
}

