namespace Slic3r::GUI::JusPrin {

// Hears OrcaSlicer's send dialogs report a job that went out, for the chat's
// print marker. OrcaSlicer queues one event on the Plater when its job
// succeeds: print-finished from Select Machine (sent and started; the event
// carries the device id) and send-finished from Send to Printer (stored on the
// printer; the event carries the project name). A job that fails queues
// neither, and its words stay in OrcaSlicer's dialog.
//
// wx calls the handler bound last first, so these run before OrcaSlicer's own
// handlers, which close the dialog and do not skip; each skips on to them.
class PrintMarkers : public wxEvtHandler
{
public:
    // `kind` is an Agent::PrinterEvent kind; `detail` is the event's string.
    using Sink = std::function<void(const char* kind, const std::string& detail)>;

    PrintMarkers(wxEvtHandler& plater, wxEventType print_finished, wxEventType send_finished, Sink sink);
    ~PrintMarkers() override;

    PrintMarkers(const PrintMarkers&)            = delete;
    PrintMarkers& operator=(const PrintMarkers&) = delete;

private:
    void on_print_finished(wxCommandEvent& event);
    void on_send_finished(wxCommandEvent& event);

    wxWeakRef<wxEvtHandler> m_plater;
    wxEventType             m_print_finished;
    wxEventType             m_send_finished;
    Sink                    m_sink;
};

} // namespace Slic3r::GUI::JusPrin

#include "PrintMarkers.hpp"

#include "slic3r/GUI/JusPrin/Agent/AgentProtocol.hpp"

#include <utility>

namespace Slic3r::GUI::JusPrin {

PrintMarkers::PrintMarkers(wxEvtHandler& plater, wxEventType print_finished, wxEventType send_finished, Sink sink)
    : m_plater(&plater), m_print_finished(print_finished), m_send_finished(send_finished), m_sink(std::move(sink))
{
    plater.Bind(wxEventTypeTag<wxCommandEvent>(m_print_finished), &PrintMarkers::on_print_finished, this);
    plater.Bind(wxEventTypeTag<wxCommandEvent>(m_send_finished), &PrintMarkers::on_send_finished, this);
}

PrintMarkers::~PrintMarkers()
{
    // The Plater may already be gone when the shell goes with the frame.
    if (m_plater) {
        m_plater->Unbind(wxEventTypeTag<wxCommandEvent>(m_print_finished), &PrintMarkers::on_print_finished, this);
        m_plater->Unbind(wxEventTypeTag<wxCommandEvent>(m_send_finished), &PrintMarkers::on_send_finished, this);
    }
}

void PrintMarkers::on_print_finished(wxCommandEvent& event)
{
    event.Skip();
    if (m_sink)
        m_sink(Agent::PrinterEvent::kSent, event.GetString().ToStdString(wxConvUTF8));
}

void PrintMarkers::on_send_finished(wxCommandEvent& event)
{
    event.Skip();
    if (m_sink)
        m_sink(Agent::PrinterEvent::kUploaded, event.GetString().ToStdString(wxConvUTF8));
}

} // namespace Slic3r::GUI::JusPrin

