// The chat's print marker hears OrcaSlicer's send-finished events before
// OrcaSlicer's own handlers, which close the send dialog and do not skip.
// Linked against the application library, because the listener is wx's.

#include <catch2/catch_all.hpp>

#include "slic3r/GUI/JusPrin/Agent/AgentProtocol.hpp"
#include "slic3r/GUI/JusPrin/Shell/PrintMarkers.hpp"

#include <wx/init.h>

#include <memory>
#include <string>
#include <vector>

using namespace Slic3r::GUI::JusPrin;

namespace {

const wxEventType kPrintFinished       = wxNewEventType();
const wxEventType kSendFinished        = wxNewEventType();
const wxEventType kCalibrationFinished = wxNewEventType();

struct Heard
{
    std::string kind;
    std::string detail;
};

// Stands in for the Plater: OrcaSlicer binds its handlers when the Plater is
// built, so they are bound before the shell's, and they do not skip.
struct FakePlater : wxEvtHandler
{
    std::vector<wxEventType> orca_handled;

    FakePlater()
    {
        for (const wxEventType type : {kPrintFinished, kSendFinished, kCalibrationFinished})
            Bind(wxEventTypeTag<wxCommandEvent>(type), [this, type](wxCommandEvent&) { orca_handled.push_back(type); });
    }

    void queue_finished(wxEventType type, const std::string& text)
    {
        wxCommandEvent event(type);
        event.SetString(wxString::FromUTF8(text));
        ProcessEvent(event);
    }
};

} // namespace

TEST_CASE("each successful send is heard once, before OrcaSlicer's own handler", "[print-marker]")
{
    wxInitializer wx;
    REQUIRE(wx.IsOk());
    FakePlater         plater;
    std::vector<Heard> heard;
    auto markers = std::make_unique<PrintMarkers>(plater, kPrintFinished, kSendFinished,
                                                  [&](const char* kind, const std::string& detail) { heard.push_back({kind, detail}); });

    plater.queue_finished(kPrintFinished, "FAKE001");
    REQUIRE(heard.size() == 1);
    CHECK(heard[0].kind == Slic3r::GUI::JusPrin::Agent::PrinterEvent::kSent);
    CHECK(heard[0].detail == "FAKE001");
    // OrcaSlicer's handler still ran, so its dialog still closes.
    REQUIRE(plater.orca_handled.size() == 1);
    CHECK(plater.orca_handled[0] == kPrintFinished);

    plater.queue_finished(kSendFinished, "Tape_4_3MF");
    REQUIRE(heard.size() == 2);
    CHECK(heard[1].kind == Slic3r::GUI::JusPrin::Agent::PrinterEvent::kUploaded);
    CHECK(heard[1].detail == "Tape_4_3MF");
    CHECK(plater.orca_handled.size() == 2);

    SECTION("another job's completion is not a send") {
        plater.queue_finished(kCalibrationFinished, "FAKE001");
        CHECK(heard.size() == 2);
        CHECK(plater.orca_handled.size() == 3);
    }
    SECTION("once the shell is gone, nothing is heard and OrcaSlicer is unchanged") {
        markers.reset();
        plater.queue_finished(kPrintFinished, "FAKE001");
        CHECK(heard.size() == 2);
        CHECK(plater.orca_handled.size() == 3);
    }
}

TEST_CASE("a send that fails raises no event, so nothing is heard", "[print-marker]")
{
    // OrcaSlicer's job writes a failure into its dialog and queues neither
    // event; the listener sees only those events.
    wxInitializer wx;
    REQUIRE(wx.IsOk());
    FakePlater         plater;
    std::vector<Heard> heard;
    PrintMarkers       markers(plater, kPrintFinished, kSendFinished,
                               [&](const char* kind, const std::string& detail) { heard.push_back({kind, detail}); });
    CHECK(heard.empty());
    CHECK(plater.orca_handled.empty());
}

TEST_CASE("a Plater that goes first leaves the listener nothing to unbind", "[print-marker]")
{
    wxInitializer wx;
    REQUIRE(wx.IsOk());
    auto plater  = std::make_unique<FakePlater>();
    auto markers = std::make_unique<PrintMarkers>(*plater, kPrintFinished, kSendFinished, [](const char*, const std::string&) {});
    plater.reset();
    REQUIRE_NOTHROW(markers.reset());
}
